window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bc94ce912e126716"]={"versions": [{"id": "FIG-bc94ce912e126716", "releases": ["R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Wertebereichs- und Abbildungsdiagramm für AUTOSAR Classic (TPS Software Component Template). Es stellt die Beziehung und Transformation von Definitions- und Wertebereichen über verschiedene Abstraktionsebenen des AUTOSAR-Typsystems dar – von der physikalischen Domäne bis zur maschinennahen Speicherrepräsentation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in vier vertikal geschichtete Modellierungsebenen:</p>\n<ul class=\"fig-list\"><li><strong>ApplicationDataType</strong>: Definiert physikalische Wertebereiche über physikalische Grenzen (<code>Lower [unit]</code>, <code>Upper [unit]</code>) und <code>physConstrs of ApplicationDataType</code>.\n</li><li><strong>CompuMethod</strong>: Spezifiziert die Berechnungs- und Umrechnungsvorschrift mit eigenen Definitionsgrenzen (<code>limits of CompuMethod</code>).\n</li><li><strong>ImplementationDataType</strong>: Repräsentiert den implementierungsspezifischen Datentyp im Software-Code mit internen Wertebereichsgrenzen (<code>internalConstrs of ImplementationDataType</code>) sowie den abgebildeten internen Grenzen des ApplicationDataTypes (<code>internalConstrs of ApplicationDataType</code>).\n</li><li><strong>BaseType</strong>: Definiert den maschinellen Wertebereich des primitiven Basisdatentyps (<code>range by BaseType</code> von <code>0</code> bis <code>2^n</code>).\n</li></ul>\n<p class=\"fig-p\">Zusätzlich werden über vertikale rote Hilfslinien zwei Kategorien von Ersatz- bzw. Ungültigkeitswerten (<code>InvalidValue</code>) verortet:</p>\n<ul class=\"fig-list\"><li><code>InvalidValue transparent to the component</code> (außerhalb der Komponentengültigkeit bzw. vor der Abbildung transparent durchgeleitet)\n</li><li><code>InvalidValue known to the component</code> (innerhalb der Erkennungsdomäne der Komponente).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die physikalischen Grenzen (<code>Lower [unit]</code>, <code>Upper [unit]</code>) des <code>ApplicationDataType</code> werden über die Abbildungsvorschrift der <code>CompuMethod</code> in interne Ganzzahl-/Rohwerte umgerechnet, visualisiert durch gestrichelte Pfeillinien, die in <code>internalConstrs of ApplicationDataType</code> auf Ebene des <code>ImplementationDataType</code> münden. Diese internen Wertebereiche liegen innerhalb der durch <code>internalConstrs of ImplementationDataType</code> sowie <code>range by BaseType</code> definierten Speicherintervalle. Die roten Markierungslinien veranschaulichen, wo definierte <code>InvalidValue</code>-Werte relativ zu den physikalischen und internen Gültigkeitsbereichen liegen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ermöglicht die semantisch korrekte Konfiguration von Datenkonvertierungen und Wertebereichsprüfungen in AUTOSAR-Modellen. Entwickler müssen sicherstellen, dass die physikalischen Grenzen (<code>physConstrs</code>) über die Skalierung der <code>CompuMethod</code> vollständig innerhalb des Wertebereichs des gewählten <code>ImplementationDataType</code> und dessen <code>BaseType</code> abbildbar sind, ohne dass es zu unbeabsichtigten Überläufen kommt. Zudem ist zu beachten, ob definierte <code>InvalidValue</code>-Werte für Komponenten transparent bleiben oder innerhalb des internen Verarbeitungsbereichs liegen.</p>"}, {"id": "FIG-a5ae1a16c69e7a66", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Wertebereichs- und Abbildungsdiagramm für AUTOSAR Classic (TPS Software Component Template). Es stellt die Beziehung und Transformation von Definitions- und Wertebereichen über verschiedene Abstraktionsebenen des AUTOSAR-Typsystems dar – von der physikalischen Domäne bis zur maschinennahen Speicherrepräsentation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in vier vertikal geschichtete Modellierungsebenen:</p>\n<ul class=\"fig-list\"><li><strong>ApplicationDataType</strong>: Definiert physikalische Wertebereiche über physikalische Grenzen (<code>Lower [unit]</code>, <code>Upper [unit]</code>) und <code>physConstrs of ApplicationDataType</code>.\n</li><li><strong>CompuMethod</strong>: Spezifiziert die Berechnungs- und Umrechnungsvorschrift mit eigenen Definitionsgrenzen (<code>limits of CompuMethod</code>).\n</li><li><strong>ImplementationDataType</strong>: Repräsentiert den implementierungsspezifischen Datentyp im Software-Code mit internen Wertebereichsgrenzen (<code>internalConstrs of ImplementationDataType</code>) sowie den berechneten internen Grenzen des ApplicationDataTypes (<code>computed internalConstrs of ApplicationDataType</code>).\n</li><li><strong>BaseType</strong>: Definiert den maschinellen Wertebereich des primitiven Basisdatentyps (<code>range by BaseType</code> von <code>0</code> bis <code>2^n</code>).\n</li></ul>\n<p class=\"fig-p\">Zusätzlich werden über vertikale rote Hilfslinien zwei Kategorien von Ersatz- bzw. Ungültigkeitswerten (<code>InvalidValue</code>) verortet:</p>\n<ul class=\"fig-list\"><li><code>InvalidValue transparent to the component</code>\n</li><li><code>InvalidValue known to the component</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die physikalischen Grenzen (<code>Lower [unit]</code>, <code>Upper [unit]</code>) des <code>ApplicationDataType</code> werden über die Abbildungsvorschrift der <code>CompuMethod</code> in interne Ganzzahl-/Rohwerte umgerechnet, visualisiert durch gestrichelte Pfeillinien, die in <code>computed internalConstrs of ApplicationDataType</code> auf Ebene des <code>ImplementationDataType</code> münden. Diese internen Wertebereiche liegen innerhalb der durch <code>internalConstrs of ImplementationDataType</code> sowie <code>range by BaseType</code> definierten Speicherintervalle. Die roten Markierungslinien veranschaulichen, wo definierte <code>InvalidValue</code>-Werte relativ zu den physikalischen und internen Gültigkeitsbereichen liegen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ermöglicht die semantisch korrekte Konfiguration von Datenkonvertierungen und Wertebereichsprüfungen in AUTOSAR-Modellen. Entwickler müssen sicherstellen, dass die physikalischen Grenzen (<code>physConstrs</code>) über die Skalierung der <code>CompuMethod</code> vollständig innerhalb des Wertebereichs des gewählten <code>ImplementationDataType</code> und dessen <code>BaseType</code> abbildbar sind, ohne dass es zu unbeabsichtigten Überläufen kommt. Zudem ist zu beachten, ob definierte <code>InvalidValue</code>-Werte für Komponenten transparent bleiben oder innerhalb des internen Verarbeitungsbereichs liegen.</p>"}], "trans": [{"from": "FIG-bc94ce912e126716", "to": "FIG-a5ae1a16c69e7a66", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Beschriftung des Wertebereichs zwischen <code>CompuMethod</code> und <code>ImplementationDataType</code> von <code>internalConstrs of ApplicationDataType</code> in <code>computed internalConstrs of ApplicationDataType</code> präzisiert.\n</li></ul>"}]};
